<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { Plus, RefreshCw, Rocket, ExternalLink, Server, GitCommitHorizontal, RadioTower } from 'lucide-vue-next'; import { api, post, statusText, when } from '../api'; import { session, router } from '../main'; import { PageHeader } from '../components/Common.vue'
const rows=ref<any[]>([]),loading=ref(true),error=ref(''); async function load(){loading.value=true;try{rows.value=await api('/dashboard')}catch(e:any){error.value=e.message}finally{loading.value=false}}; async function deploy(p:any){if(!confirm(`确认发布项目「${p.name}」的 SVN 最新修订？`))return;try{const r:any=await post(`/projects/${p.id}/deployments`,{revision:null});router.push(`/projects/${p.id}/release?task=${r.id}`)}catch(e:any){alert(e.message)}} onMounted(load)
</script>
<template><PageHeader eyebrow="OPERATIONS OVERVIEW" title="项目总览" description="所有项目的版本、运行状态与发布活动一览。"><button class="btn ghost" @click="load"><RefreshCw :size="16"/>刷新</button><RouterLink v-if="session.user?.role==='Admin'" class="btn primary" to="/projects/new"><Plus :size="17"/>新建项目</RouterLink></PageHeader><div class="metric-strip"><div><small>项目总数</small><strong>{{rows.length}}</strong></div><div><small>运行中</small><strong>{{rows.filter(x=>x.runtime.state==='Running').length}}</strong></div><div><small>发布异常</small><strong>{{rows.filter(x=>['Failed','Interrupted'].includes(x.lastDeployment?.status)).length}}</strong></div><span class="pulse-line"></span></div><div v-if="error" class="alert error">{{error}}</div><div v-if="loading" class="empty">正在读取项目状态…</div><div v-else-if="!rows.length" class="empty-card"><Server/><h3>还没有发布项目</h3><p>创建第一个项目，配置 SVN 地址与标准源码目录。</p><RouterLink class="btn primary" to="/projects/new">开始配置</RouterLink></div><section v-else class="project-grid"><article v-for="p in rows" :key="p.id" class="project-card"><div class="card-top"><span class="project-index">{{String(rows.indexOf(p)+1).padStart(2,'0')}}</span><span :class="['state-pill',p.runtime.state==='Running'?'live':'']"><i></i>{{statusText(p.runtime.state)}}</span></div><h2>{{p.name}}</h2><p>{{p.description||'暂无项目说明'}}</p><div v-if="p.endpoints?.length" class="endpoint-list"><span v-for="endpoint in p.endpoints" :key="endpoint"><RadioTower/>{{endpoint}}</span></div><div v-else class="endpoint-list muted"><span><RadioTower/>未读取到 Kestrel 端口</span></div><div class="version-panel"><span><GitCommitHorizontal/>SVN REVISION</span><strong>{{p.svnRevision ? `r${p.svnRevision}` : '尚未发布'}}</strong><small>{{p.currentVersion||'—'}}</small></div><div class="last-run"><span>最近发布</span><b>{{statusText(p.lastDeployment?.status||'暂无')}}</b><time>{{when(p.lastDeployment?.createdAtUtc)}}</time></div><footer><button v-if="session.user?.role!=='Viewer'" class="btn launch" :disabled="p.lastDeployment&&!['Succeeded','Failed','Cancelled','Interrupted','RolledBack'].includes(p.lastDeployment.status)" @click="deploy(p)"><Rocket :size="16"/>发布最新</button><button class="btn icon-text" @click="router.push(`/projects/${p.id}/overview`)">进入项目<ExternalLink :size="15"/></button></footer></article></section></template>
